INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65999591', 65999591, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS23 LAPAS PEREMPUAN KELAS II A SUNGGUMINASA', 'Pengadaan Pekerjaan Konstruksi Pemeliharaan Gedung Tahap I pada Lapas Perempuan Kelas IIA Sungguminasa - Sulawesi Selatan Tahun Anggaran 2026', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Sulawesi Selatan, Gowa (Kab.)', 199000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1020 M2', 'Pemeliharaan konstruksi gedung bertingkat di Lapas Perempuan Kelas IIA Sungguminasa dengan luas total sekitar 1.020 m². Kegiatan meliputi pekerjaan persiapan, pengerjaan struktur utama bangunan, pemasangan dinding, lantai, atap, instalasi listrik dan plumbing, serta penyelesaian arsitektur hingga bangunan siap digunakan.', 'Pekerjaan konstruksi gedung bertingkat ini dilaksanakan dengan mengacu pada standar teknis konstruksi nasional serta ketentuan keselamatan dan kesehatan kerja. Seluruh material yang digunakan harus baru, berkualitas baik, dan memenuhi standar SNI atau standar teknis yang berlaku. Struktur bangunan menggunakan material beton bertulang atau baja yang mampu menjamin kekuatan dan kestabilan bangunan. Pekerjaan arsitektur meliputi penyelesaian dinding, lantai, plafon, dan atap dengan bahan yang tahan lama, mudah dirawat, serta sesuai standar kenyamanan bangunan gedung.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2462350);
