INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66002324', 66002324, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Pengadaan Lift Pasien untuk Gedung PHTC Batch 1', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 15000000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '10.0 PT', 'Pekerjaan meliputi pengadaan, pengiriman, pemasangan, pengujian, dan commissioning lift pasien pada Gedung PHTC Batch 1 di 10 lokus sampai berfungsi dengan baik dan laik operasi sesuai ketentuan. Kegiatan diawali dengan survei lokasi, pengukuran teknis, penyusunan shop drawing, dan koordinasi pelaksanaan. Selanjutnya dilakukan instalasi komponen mekanikal dan elektrikal, pemasangan rel, kabin, mesin penggerak, panel kontrol, pintu lift, serta sistem keselamatan. Setelah pemasangan dilakukan pengujian fungsi dan beban, pelatihan pengoperasian, penyerahan dokumen teknis, serta pemeliharaan selama masa garansi.', 'Lift yang disediakan merupakan lift pasien (hospital bed elevator) dengan kapasitas angkut yang mampu mengakomodasi tempat tidur pasien beserta pendamping, memiliki sistem penggerak yang andal, pengaturan kecepatan yang halus, serta tingkat kebisingan dan getaran yang rendah. Dimensi kabin dan lebar bukaan pintu harus memungkinkan mobilisasi pasien secara aman dan nyaman, dilengkapi interior berbahan yang kuat, higienis, mudah dibersihkan, dan tahan korosi, handrail, pencahayaan yang cukup, indikator lantai, voice announcer, dan sistem komunikasi darurat. Sistem kontrol menggunakan teknologi berbasis mikroprosesor dengan fitur automatic rescue device, overload indicator, door sensor full height, governor, safety gear, buffer, emergency alarm, serta mendukung operasi saat kondisi kebakaran. Instalasi lift harus memenuhi Standar Nasional Indonesia (SNI), persyaratan K3, standar instalasi listrik yang berlaku, serta ketentuan pesawat angkat dan angkut. Penyedia wajib memberikan garansi, menjamin ketersediaan suku cadang, serta layanan purna jual dengan waktu respon sesuai ketentuan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2469300);
