INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65966191', 65966191, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pemeliharaan Sistem Transportasi Gedung (Lift) Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 199800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 Paket', 'Ruang Lingkup Pekerjaan: 1. Pemeliharaan berkala yang meliputi: No Uraian Pekerjaan Jadwal 1 Pemeliharaan Berkala a) Pemeriksaan Oli mesin gear box dan oli rell, 1x sebulan b) Pemeriksaan Air accu ARD, 1x sebulan c) Pemeriksaan lampu penerangan sangkar, 1x sebulan d) Pemeriksaan fan sangkar, 1x sebulan e) Pemeriksaan leveling sangkar, 1x sebulan f) Pemeriksaan lampu-lampu indicator, 1x sebulan g) Pemeriksaan lampu-lampu tombol, 1x sebulan h) Pemeriksaan wire rope. 1x sebulan i) Pemeriksaan Buka tutup pintu lift dalam keadaan lancer dan tidak menimbulkan bunyi; 1x sebulan j) Pemeriksaan Seluruh safety switch, 1x sebulan k) Pemeriksaan switch over load, 1x sebulan l) Pemeriksaan fire man, 1x sebulan m) Pemeriksaan tes ARD, Main dan shave pulley, 1x sebulan n) Pemeriksaan governour, 1x sebulan o) Pemeriksaan ruang pit, 1x sebulan p) Pemeriksaan leveling wire rope terhadap buffer, 1x sebulan q) Pemeriksaan klem rell sangkar dan counter weight. 1x sebulan r) Pemeriksaan seluruh komponen CPU board harus berfungsi dengan baik; 1x sebulan 2. Perpanjangan izin pemakaian Lift dan Reksa Uji terhadap 6 (enam) Lift; 3. Melakukan penggantian terhadap sparepart di luar pemeluharaan/pemeriksaan berkala; 4. Menyampaikan laporan tertulis setiap bulan atas hasil pemeriksaan yang telah dilakukan termasuk dengan rekomendasi untuk pemeriksaan selanjutnya; 5. Bersedia memenuhi panggilan pemeriksaan kemacetan pada pesawat jika pengguna jasa atau petugas resmi memberi tahu kejadian tersebut disamping pemeriksaan; Jaminan Kualitas 1. Penyedia Barang/Jasa harus melaksanakan pekerjaan dengan baik sesuai dengan persyaratan teknis yang telah ditetapkan PPK dan memberikan hasil pekerjaan yang sesuai dengan dokumen kontrak; 2. Segala resiko kecelakaan pekerjaan yang terjadi pada saat pelaksanaan ditanggung oleh Penyedia Jasa; 3. Penyedia Barang/Jasa harus memahami dan menguasai seluruh tahapan pekerjaan sesuai target yang telah disepakati dengan PPK dan telah memperhitungkan segala resiko akibat yang mungkin akan timbul dalam proses pelaksanaan pekerjaan; 4. Penyedia Jasa harus menyediakan peralatan kerja yang sesuai dengan kebutuhan pelaksanaan pekerjaan dan standar K3; 5. Apabila Penyedia Jasa diminta untuk menjelaskan secara rinci mengenai segala sesuatu yang berhubungan dengan pekerjaan ini, maka Penyedia Jasa harus sanggup memberikan bukti-bukti mengenai hal-hal tersebut secara informative (baik lisan maupun tertulis) yang disertai dengan foto dokumentasi. 6. Apabila pada saat pelaksanaan pekerjaan ada temuan kerusakan unit lift yang sudah tidak dapat di perbaiki harus segera membuat laporan tertulis untuk diadakan penggantian. Pelaporan 1. Laporan setiap pelaksanakan kegiatan atau pekerjaan pemeliharaan rutin; 2. Dokumentasi foto hasil pelaksanaan pekerjaan', 'Ruang Lingkup Pekerjaan: 1. Pemeliharaan berkala yang meliputi: No Uraian Pekerjaan Jadwal 1 Pemeliharaan Berkala a) Pemeriksaan Oli mesin gear box dan oli rell, 1x sebulan b) Pemeriksaan Air accu ARD, 1x sebulan c) Pemeriksaan lampu penerangan sangkar, 1x sebulan d) Pemeriksaan fan sangkar, 1x sebulan e) Pemeriksaan leveling sangkar, 1x sebulan f) Pemeriksaan lampu-lampu indicator, 1x sebulan g) Pemeriksaan lampu-lampu tombol, 1x sebulan h) Pemeriksaan wire rope. 1x sebulan i) Pemeriksaan Buka tutup pintu lift dalam keadaan lancer dan tidak menimbulkan bunyi; 1x sebulan j) Pemeriksaan Seluruh safety switch, 1x sebulan k) Pemeriksaan switch over load, 1x sebulan l) Pemeriksaan fire man, 1x sebulan m) Pemeriksaan tes ARD, Main dan shave pulley, 1x sebulan n) Pemeriksaan governour, 1x sebulan o) Pemeriksaan ruang pit, 1x sebulan p) Pemeriksaan leveling wire rope terhadap buffer, 1x sebulan q) Pemeriksaan klem rell sangkar dan counter weight. 1x sebulan r) Pemeriksaan seluruh komponen CPU board harus berfungsi dengan baik; 1x sebulan 2. Perpanjangan izin pemakaian Lift dan Reksa Uji terhadap 6 (enam) Lift; 3. Melakukan penggantian terhadap sparepart di luar pemeluharaan/pemeriksaan berkala; 4. Menyampaikan laporan tertulis setiap bulan atas hasil pemeriksaan yang telah dilakukan termasuk dengan rekomendasi untuk pemeriksaan selanjutnya; 5. Bersedia memenuhi panggilan pemeriksaan kemacetan pada pesawat jika pengguna jasa atau petugas resmi memberi tahu kejadian tersebut disamping pemeriksaan; Jaminan Kualitas 1. Penyedia Barang/Jasa harus melaksanakan pekerjaan dengan baik sesuai dengan persyaratan teknis yang telah ditetapkan PPK dan memberikan hasil pekerjaan yang sesuai dengan dokumen kontrak; 2. Segala resiko kecelakaan pekerjaan yang terjadi pada saat pelaksanaan ditanggung oleh Penyedia Jasa; 3. Penyedia Barang/Jasa harus memahami dan menguasai seluruh tahapan pekerjaan sesuai target yang telah disepakati dengan PPK dan telah memperhitungkan segala resiko akibat yang mungkin akan timbul dalam proses pelaksanaan pekerjaan; 4. Penyedia Jasa harus menyediakan peralatan kerja yang sesuai dengan kebutuhan pelaksanaan pekerjaan dan standar K3; 5. Apabila Penyedia Jasa diminta untuk menjelaskan secara rinci mengenai segala sesuatu yang berhubungan dengan pekerjaan ini, maka Penyedia Jasa harus sanggup memberikan bukti-bukti mengenai hal-hal tersebut secara informative (baik lisan maupun tertulis) yang dis